import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/routing/app_router.dart';import '../../../providers/auth_provider.dart';
class VerifyEmailScreen extends StatelessWidget{const VerifyEmailScreen({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Verify email')),body:Padding(padding:const EdgeInsets.all(24),child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.mark_email_read_outlined,size:60),const Text('Check your ALU inbox and open the verification link.',textAlign:TextAlign.center),const SizedBox(height:16),FilledButton(onPressed:()async{final ok=await context.read<AuthProvider>().refreshVerification();if(!context.mounted)return;if(ok){Navigator.pushNamedAndRemoveUntil(context,AppRouter.home,(_)=>false);}else{ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Email is not verified yet.')));}},child:const Text('I verified my email')),TextButton(onPressed:()=>context.read<AuthProvider>().resendVerification(),child:const Text('Resend verification')),TextButton(onPressed:()=>Navigator.pushNamedAndRemoveUntil(context,AppRouter.login,(_)=>false),child:const Text('Back to login')]))));}}
